# ── Helper ───────────────────────────────────────────────────────

def _make_acronym(text):
    skip = {'and', '&', 'the', 'of', 'for', 'a', 'an', 'in', 'at', 'to'}
    words = re.sub(r'[^a-zA-Z\s]', '', text).split()
    result = ''.join(w[0].upper() for w in words if w.lower() not in skip and w)
    return result or 'MD'


