def seed_options(apps, schema_editor):
    RequestedByOption = apps.get_model('material_rework', 'RequestedByOption')
    for name in ['Warehouse', 'Production', 'Order Management']:
        RequestedByOption.objects.get_or_create(name=name)


def populate_reference_numbers(apps, schema_editor):
    DispositionBatch = apps.get_model('material_rework', 'DispositionBatch')
    year = timezone.now().year
    for batch in DispositionBatch.objects.select_related('vertical').order_by('id'):
        if not batch.reference_number:
            acronym = _make_acronym(batch.vertical.name)
            batch.reference_number = f"{acronym}-{year}{batch.pk:07d}"
            batch.save(update_fields=['reference_number'])


def create_mr_groups(apps, schema_editor):
    Group = apps.get_model('auth', 'Group')
    group_names = [
        'Material Rework Admin',
        'Material Rework User',
        'MR Production',
        'MR Warehouse',
        'MR HOD',
    ]
    for name in group_names:
        Group.objects.get_or_create(name=name)


