# ── Routing seeds, from 0003_seed_routing_rules ───────────────────

#: Requested By name → the chain that requester's rework follows.
#: Names are matched case-insensitively against the RequestedByOption master,
#: which already holds exactly these four.
REQUESTED_BY_FLOWS = {
    "Warehouse": ["om", "ppic", "production"],
    "Order Management": ["ppic", "production"],
    "Planning": ["production"],
    # Production raising its own rework has nothing to approve — the batch
    # goes straight into the warehouse round trip carrying the slot the
    # uploader committed to.
    "Production": ["warehouse"],
}

#: Type of Rework name → chain. These win outright over the requester's flow,
#: which is the point of them: a Damage or Wrapping job goes straight to
#: production no matter who raised it.
REWORK_TYPE_FLOWS = {
    "Damage": ["production"],
    "Wrapping": ["production"],
}

OM_GROUP = "MR Order Management"


def seed(apps, schema_editor):
    RequestedByOption = apps.get_model("material_rework", "RequestedByOption")
    ReworkType = apps.get_model("material_rework", "ReworkType")
    RoutingRule = apps.get_model("material_rework", "RoutingRule")
    Group = apps.get_model("auth", "Group")

    Group.objects.get_or_create(name=OM_GROUP)

    for name, stages in REQUESTED_BY_FLOWS.items():
        option = RequestedByOption.objects.filter(name__iexact=name).first()
        if option is None:
            # An installation that renamed or removed the option. Skipped
            # rather than created: inventing a Requested By row here would put
            # an option on the upload form that this deployment chose not to
            # have.
            continue
        RoutingRule.objects.get_or_create(
            requested_by=option,
            defaults={"stages": stages, "is_active": True, "notes": "Seeded default flow."},
        )

    for name, stages in REWORK_TYPE_FLOWS.items():
        rework_type = ReworkType.objects.filter(name__iexact=name).first()
        if rework_type is None:
            continue
        RoutingRule.objects.get_or_create(
            rework_type=rework_type,
            defaults={"stages": stages, "is_active": True, "notes": "Seeded default flow."},
        )


def unseed(apps, schema_editor):
    RoutingRule = apps.get_model("material_rework", "RoutingRule")
    # Only the untouched seeds. A rule whose note or stages an admin has since
    # changed is theirs, and a rollback has no business deleting it.
    for name, stages in REQUESTED_BY_FLOWS.items():
        RoutingRule.objects.filter(
            requested_by__name__iexact=name, stages=stages, notes="Seeded default flow.",
        ).delete()
    for name, stages in REWORK_TYPE_FLOWS.items():
        RoutingRule.objects.filter(
            rework_type__name__iexact=name, stages=stages, notes="Seeded default flow.",
        ).delete()


